library(data.table)
base <- "/data/y01014/diliyaer/BLCA_CAF_project/GDF15_CAF_project"; tar <- file.path(base,"02_external_scRNA_downloads/GSE135337/GSE135337_RAW.tar"); out <- file.path(base,"analysis_revisions_20260906/GSE135337_CAF_myeloid_LR"); dir.create(out,recursive=TRUE,showWarnings=FALSE)
lr <- data.table(ligand=c("CXCL12","CCL2","CCL5","CSF1","TGFB1","TGFB2","PDGFA","IL6","COL1A1","COL3A1","FN1"),receptor=c("CXCR4","CCR2","CCR5","CSF1R","TGFBR1","TGFBR2","PDGFRA","IL6R","ITGA1","ITGA1","ITGA5"),pair=c("CXCL12-CXCR4","CCL2-CCR2","CCL5-CCR5","CSF1-CSF1R","TGFB1-TGFBR1","TGFB2-TGFBR2","PDGFA-PDGFRA","IL6-IL6R","COL1A1-ITGA1","COL3A1-ITGA1","FN1-ITGA5"))
cs <- fread(file.path(base,"analysis_revisions_20260906/GSE135337_patient_level_CCDC80_TME/GSE135337_cell_level_scores.csv"),select=c("cell_id","patient_id","sample_id","CCDC80","CAF","Myeloid"))
fs <- system2("tar",c("-tf",shQuote(tar)),stdout=TRUE); fs <- fs[grepl("_BC[1-7]_gene_cell_exprs_table",basename(fs))]; ans <- list()
for(f in fs){ sid<-sub("_gene_cell_exprs_table.*$","",basename(f)); cmd<-paste("tar -xOf",shQuote(tar),shQuote(f),"| gzip -dc"); x<-fread(cmd=cmd,data.table=FALSE,check.names=FALSE); gene<-toupper(x[[2]]); mat<-as.matrix(x[,-c(1,2),drop=FALSE]); storage.mode(mat)<-"numeric"; rownames(mat)<-gene; lib<-colSums(mat); norm<-log1p(t(t(mat)/pmax(lib,1)*10000)); cc<-cs[sample_id==sid]; cc<-cc[match(colnames(norm),cell_id)]; for(i in seq_len(nrow(lr))){l<-lr$ligand[i];r<-lr$receptor[i]; ans[[length(ans)+1]]<-data.table(sample_id=sid,patient_id=unique(cc$patient_id),pair=lr$pair[i],ligand=l,receptor=r,CAF_ligand=if(l%in%rownames(norm))mean(norm[l,][cc$CAF==TRUE],na.rm=TRUE) else NA_real_,Myeloid_receptor=if(r%in%rownames(norm))mean(norm[r,][cc$Myeloid==TRUE],na.rm=TRUE) else NA_real_)}}
d<-rbindlist(ans); d[,LR_potential:=CAF_ligand*Myeloid_receptor]; fwrite(d,file.path(out,"GSE135337_patient_LR_potential.csv")); top<-d[,.(mean_LR=mean(LR_potential,na.rm=TRUE),n_patients=uniqueN(patient_id)),by=.(pair,ligand,receptor)][order(-mean_LR)]; fwrite(top,file.path(out,"GSE135337_LR_ranked_pairs.csv")); writeLines(c("Targeted CAF-to-myeloid ligand-receptor analysis","Potential score = mean ligand expression in CAF x mean receptor expression in myeloid cells.","This is a prioritization score, not causal communication proof."),file.path(out,"RUN_STATUS.txt"))
